  function renderChangeItem(runId,item){if(!item||!item.id)return null;let view=state.reviewItemsById.get(item.id);if(!view){const row=document.createElement('div');row.className='entity-row';const b=document.createElement('button');b.className='change';const k=document.createElement('div');k.className='kind';const t=document.createElement('div');t.className='target';b.append(k,t);row.append(b,inspectButton('change',{runId,changeId:item.id},'Inspect change record in Pharo'));$('changes').appendChild(row);view={row,b,k,t,item:null};state.reviewItemsById.set(item.id,view)}view.item=item;view.b.className='change'+(item.reverted?' reverted':'');view.k.textContent=(item.scope||'change')+' / '+(item.kind||'')+(item.reverted?' · reverted':'');view.t.textContent=item.target||item.id;view.t.title=item.target||item.id;view.b.title=(item.rollbackSafety||'')+(item.diffAvailable?' · diff available':'');view.b.onclick=()=>showChange(runId,item.id);return view.row}
