  async function refreshReview(runId,afterChangeId=null,append=false){if(!runId){clearReview();return}const params={runId,limit:50};if(afterChangeId)params.afterChangeId=afterChangeId;const review=await call('runs.review',params);if(state.runId&&state.runId!==runId&&state.reviewRunId!==runId)return;state.reviewRunId=runId;if(!append){$('changes').textContent='';state.reviewItemsById.clear()}for(const item of review.items||[])renderChangeItem(runId,item);state.reviewNextChangeId=review.nextChangeId;state.reviewHasMore=!!review.hasMore;$('moreChanges').classList.toggle('hidden',!state.reviewHasMore);const scopes=Object.entries(review.scopeCounts||{}).map(([k,v])=>k+': '+v).join(', ');$('reviewSummary').textContent=review.totalChangeCount+' change(s)'+(scopes?' · '+scopes:'')+' · rollback candidates: '+(review.semanticRollbackCandidateCount||0)+' · opaque: '+(review.opaqueCount||0)+' · reverted: '+(review.revertedCount||0)}
